function validate([nums, cost, k]) {
  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (cost.length !== nums.length) return 'cost must have the same length as nums.';
  if (nums.some(v => v < 1 || v > 1000)) return 'Each value of nums is between 1 and 1000.';
  if (cost.some(v => v < 1 || v > 1000)) return 'Each value of cost is between 1 and 1000.';
  if (k < 1 || k > 1000) return 'k is between 1 and 1000.';
  return null;
}

