function minimumCost(nums, cost, k) {
  const n = nums.length;
  const prefixNums = new Array(n + 1).fill(0);
  const prefixCost = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefixNums[i + 1] = prefixNums[i] + nums[i];
    prefixCost[i + 1] = prefixCost[i] + cost[i];
  }
  const totalCost = prefixCost[n];
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;
  for (let end = 1; end <= n; end++) {
    for (let start = 0; start < end; start++) {
      const pieceCost = prefixCost[end] - prefixCost[start];
      const tailCost = totalCost - prefixCost[start];
      const candidate = dp[start] + prefixNums[end] * pieceCost + k * tailCost;
      dp[end] = Math.min(dp[end], candidate);
    }
  }
  return dp[n];
}

