function minimumCost(nums, cost, k) {
  // Try every set of cut positions and price each piece straight from the definition.
  const n = nums.length;
  let best = Infinity;
  for (let mask = 0; mask < 2 ** (n - 1); mask++) {
    let total = 0;
    let order = 0;
    let first = 0;
    let runningNums = 0;
    for (let r = 0; r < n; r++) {
      runningNums += nums[r];
      const closes = r === n - 1 || Math.floor(mask / 2 ** r) % 2 === 1;
      if (!closes) continue;
      order += 1;
      let pieceCost = 0;
      for (let t = first; t <= r; t++) pieceCost += cost[t];
      total += (runningNums + k * order) * pieceCost;
      first = r + 1;
    }
    if (total < best) best = total;
  }
  return best;
}

