function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const range = () => (size === 'large' || rand() < 0.5 ? 1000 : 1 + Math.floor(rand() * 20));
  const numsTop = range();
  const costTop = range();
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * numsTop));
  const cost = Array.from({ length: n }, () => 1 + Math.floor(rand() * costTop));
  const pick = rand();
  const k = pick < 0.2 ? 1 : pick < 0.35 ? 1000 : 1 + Math.floor(rand() * (rand() < 0.5 ? 20 : 1000));
  return [nums, cost, k];
}
